INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G34 — Oracle provider mode toggle (Local Claude vs external, dormant)', 'HOW TO TEST: look for the pinned "oracle-provider-switch" toggle, top-right of any page, below the existing mock-oracle switches (🧪/✅). Click it: confirm it visually flips between "🔮 Local" and "🌐 <provider>". Right-click it: confirm it cycles the target provider label between kimi/luna. Try a real Oracle send while set to External — it should fail loud with an honest "dormant, no real key configured" error, never silently succeed or silently fall back to Local.', 'unverified', 'rpgace_core.js MODULE:oracleProviderMode', 'River III', 'Level 3 (module)', NULL, (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G34'));
INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G38 — Level 2.5 (UI/Alex accessibility convergence point)', 'HOW TO TEST: open graphify-out/galaxy_map_level2_5.html. Confirm the 10 real card-having rivers each render with their real dashboard card(s), each card resolving to its real primary module with a working link into Level 3.', 'unverified', 'scripts/galaxy_map_level2_5.py', 'multiple', 'Level 2.5', NULL, (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G38'));
INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G39 — Load Dimension (boot/page-nav/click-load diagnostics)', 'HOW TO TEST: open graphify-out/galaxy_map_load.html. Confirm the real boot-task registration list, page-nav trigger list, and click-load trigger list all render with working links into Level 2/3.', 'unverified', 'scripts/galaxy_map_load.py', 'multiple', 'Load Dimension', NULL, (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G39'));
INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G43 — L0 map (7 peer units, no privileged gateway)', 'HOW TO TEST: open graphify-out/galaxy_map_l0.html (map view, default). Confirm all 7 real units render as bubbles with no single unit visually privileged. Click a unit — its own panel + real dimension-edges should appear. Click an edge — the real drop panel (evidence/desc, yes/no forks where they exist) should appear.', 'unverified', 'scripts/galaxy_map_l0.py', 'n/a (L0)', 'Level 0', NULL, (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G43'));
INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G44 — L0 Dimension Matrix (7x7 table view)', 'HOW TO TEST: on graphify-out/galaxy_map_l0.html, click the "📊 Table" toggle (top of page). Confirm the 7x7 grid renders and clicking a real edge cell shows the same drop-panel content as the map view''s edges do.', 'unverified', 'scripts/galaxy_map_l0.py (table view)', 'n/a (L0)', 'Level 0', 'Real, honest overlap: as of the Aug 20 2026 merge, this is the SAME physical file as G43 (galaxy_map_l0.html), reached via its own toggle rather than a separate page — not a duplicate test, a distinct real view of the same shared data.', (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G44'));
INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G45 — Supabase page (25 real tables x Level/River/Module usage)', 'HOW TO TEST: open graphify-out/galaxy_map_supabase.html. Confirm the 25 real tables list, each showing real client-side read/write touches with working links into the module(s) that touch them.', 'unverified', 'scripts/galaxy_map_supabase.py', 'multiple', 'n/a (Supabase dimension)', NULL, (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G45'));
