INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G49 — River redefinition v2 (River V split into 2 real rivers)', 'HOW TO TEST: open graphify-out/galaxy_map_river.html. Confirm River V now reads "Daily Ops: Agenda, Schedule & Journal" (not the old combined name) and a new River XVII "The Research & Intel Stream" exists with its own 5 real modules (researchTabs/intelBatchList/intelDelete/intelDedup/ciAutoPropose).', 'unverified', 'scripts/graphify_river_group.py RIVER_MODULES', 'River V, River XVII', 'Level 1 (rivers)', NULL, (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G49'));
INSERT INTO smoke_test_items (category, item_name, description, status, source_ref, galaxy_river, galaxy_level, cross_ref_note, linked_plan_item_id) VALUES ('Galaxy Development Framework — Yellow Confirm Queue', 'G50 — Oversight Docs bubble system', 'HOW TO TEST: on graphify-out/galaxy_map_l0.html, click the "Oversight Docs" unit. Confirm it renders its own real dimension-edges the same way every other L0 unit does — this item was delivered as part of G43''s own build, not a separate page.', 'unverified', 'scripts/galaxy_map_l0.py (oversight_docs unit)', 'n/a (L0)', 'Level 0', 'Already delivered as part of G43''s own build (same real evidence, not rebuilt separately) — this row exists so G50 can be independently confirmed/flipped in ceo_plan_items, per G51''s own 1:1 row-per-item design.', (SELECT id FROM ceo_plan_items WHERE plan_id = '6f8536fd-7d98-4565-9369-c75a149fce8f' AND item_code = 'G50'));
